// src/app/middlewares/logger.middleware.ts
var requestLogger = (req, res, next) => {
  const start = Date.now();
  res.on("finish", () => {
    const duration = Date.now() - start;
    const message = `[Request] ${req.method} ${req.originalUrl} - ${res.statusCode} (${duration}ms)`;
    logger_default.info(message, {
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userId: req.user?.id || "guest",
      userAgent: req.get("user-agent")
    });
  });
  next();
};

// src/app/middlewares/globalErrorHandler.ts
import status9 from "http-status";
var globalErrorHandler = (err, req, res, next) => {
  let statusCode = status9.INTERNAL_SERVER_ERROR;
  let message = "Something went wrong!";
  let errorMessages = [];
  if (err instanceof AppError_default) {
    statusCode = err.statusCode;
    message = err.message;
    errorMessages = err.message ? [{ path: "", message: err.message }] : [];
    if (statusCode < 500) {
      errorLogger.warn(`Business Error: ${message}`, {
        statusCode,
        path: req.originalUrl,
        method: req.method,
        userId: req.user?.id || "guest"
      });
    } else {
      errorLogger.error(`System Error: ${message}`, {
        statusCode,
        stack: err.stack,
        path: req.originalUrl,
        method: req.method
      });
    }
  } else if (err instanceof Error) {
    message = err.message;
    errorMessages = err.message ? [{ path: "", message: err.message }] : [];
    errorLogger.error(`Unhandled Error: ${message}`, {
      stack: err.stack,
      path: req.originalUrl,
      method: req.method
    });
  }
  res.status(statusCode).json({
    success: false,
    message,
    errorMessages,
    stack: envVariable.NODE_ENV === "development" ? err?.stack : null
  });
};

